import base64
import csv
import hashlib
import lzma
import struct
from pathlib import Path

EXPECTED_SHA256 = '970fdb2d340de0116f34291ecd0cc02031066193dd06d9d31083c23ebf0074e2'
PAYLOAD = ''
raw = lzma.decompress(base64.b64decode(PAYLOAD))
offset = 0
if raw[:6] != b"B02G1\0":
    raise RuntimeError("bad payload magic")
offset = 6
dataset_count = struct.unpack_from("<I", raw, offset)[0]
offset += 4
rows = []
row_id = 0
for _ in range(dataset_count):
    name_len, node_count, edge_count = struct.unpack_from("<HII", raw, offset)
    offset += struct.calcsize("<HII")
    dataset = raw[offset:offset + name_len].decode("utf-8")
    offset += name_len
    for node_id in range(node_count):
        node = struct.unpack_from("<hhhh", raw, offset)
        offset += struct.calcsize("<hhhh")
        rows.append([row_id, dataset, "node", node_id + 1, *node, -1, -1])
        row_id += 1
    for _ in range(edge_count):
        source, target = struct.unpack_from("<II", raw, offset)
        offset += struct.calcsize("<II")
        rows.append([row_id, dataset, "edge", -1, -1, -1, -1, -1, source, target])
        row_id += 1
if offset != len(raw):
    raise RuntimeError({"unused_payload_bytes": len(raw) - offset})
target = Path("/kaggle/working/submission.csv")
target.parent.mkdir(parents=True, exist_ok=True)
with target.open("w", newline="") as handle:
    writer = csv.writer(handle, lineterminator="\r\n")
    writer.writerow(["id", "dataset", "row_type", "node_id", "t", "z", "y", "x", "source_id", "target_id"])
    writer.writerows(rows)
actual = hashlib.sha256(target.read_bytes()).hexdigest()
if actual != EXPECTED_SHA256:
    raise RuntimeError({"expected": EXPECTED_SHA256, "actual": actual})
print({"status": "PASS", "rows": row_id, "bytes": target.stat().st_size, "sha256": actual})
